package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0           // PIC 9(4) len=4 = 0
var WsR4 int64 = 0          // PIC 9(3) len=3 = 0
var WsR100 int64 = 0        // PIC 9(3) len=3 = 0
var WsR400 int64 = 0        // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0      // PIC 99 len=2 = 0
var WsValid int64 = 0       // PIC 99 len=2 = 0
var WsBadMonth int64 = 0    // PIC 99 len=2 = 0
var WsBadDay int64 = 0      // PIC 99 len=2 = 0

var CurRec DateRec

var inputLines []string
var inputIdx int

// helpers for COBOL numeric handling
func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func trunc(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	m := pow10(digits)
	if v >= 0 {
		return v % m
	}
	// for negative, keep low-order digits with sign
	return -((-v) % m)
}

func formatNum(v int64, digits int) string {
	tv := trunc(v, digits)
	if tv < 0 {
		tv = -tv
	}
	s := fmt.Sprintf("%0*d", digits, tv)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

// ensure decimal import is used
var _ = decimal.NewFromInt(0)

func parseNumField(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// keep only digits and optional sign
	// numeric fields in file are digits only
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		// if contains non-digit, try to extract digits
		// fallback to 0
		var b strings.Builder
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				b.WriteRune(ch)
			}
		}
		if b.Len() == 0 {
			return 0
		}
		v2, _ := strconv.ParseInt(b.String(), 10, 64)
		return v2
	}
	return v
}

func MainPara() {
	// OPEN INPUT DATE-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		inputLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			// Scanner strips \n and \r, but keep content as is (excluding newline)
			// It already removed trailing \r for \r\n
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	inputIdx = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE DATE-FILE already closed
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	out := "VALID: " + formatNum(WsValid, 2) + " BAD MONTH: " + formatNum(WsBadMonth, 2) + " BAD DAY: " + formatNum(WsBadDay, 2)
	fmt.Fprintln(os.Stdout, out)
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// pad with spaces on right if shorter than 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	// parse
	CurRec.DtId = line[0:4]
	CurRec.DtYyyy = parseNumField(line[4:8])
	CurRec.DtMm = parseNumField(line[8:10])
	CurRec.DtDd = parseNumField(line[10:12])
}

func ProcessPara() {
	LeapPara()
	// EVALUATE TRUE
	if CurRec.DtMm < 1 || CurRec.DtMm > 12 {
		// ADD 1 TO WS-BAD-MONTH
		WsBadMonth = trunc(WsBadMonth+1, 2)
		// DISPLAY DT-ID " BAD MONTH " DT-MM
		out := CurRec.DtId + " BAD MONTH " + formatNum(CurRec.DtMm, 2)
		fmt.Fprintln(os.Stdout, out)
	} else {
		DaysPara()
		if CurRec.DtDd < 1 || CurRec.DtDd > WsMaxDay {
			WsBadDay = trunc(WsBadDay+1, 2)
			out := CurRec.DtId + " BAD DAY " + formatNum(CurRec.DtDd, 2) + " MAX " + formatNum(WsMaxDay, 2)
			fmt.Fprintln(os.Stdout, out)
		} else {
			WsValid = trunc(WsValid+1, 2)
			out := CurRec.DtId + " VALID " + formatNum(CurRec.DtYyyy, 4) + "-" + formatNum(CurRec.DtMm, 2) + "-" + formatNum(CurRec.DtDd, 2)
			fmt.Fprintln(os.Stdout, out)
		}
	}
	ReadPara()
}

func LeapPara() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	if 4 != 0 {
		q := CurRec.DtYyyy / 4
		r := CurRec.DtYyyy % 4
		WsQ = trunc(q, 4)
		WsR4 = trunc(r, 3)
	}
	// DIVIDE DT-YYYY BY 100 GIVING WS-Q REMAINDER WS-R100
	if 100 != 0 {
		q := CurRec.DtYyyy / 100
		r := CurRec.DtYyyy % 100
		WsQ = trunc(q, 4)
		WsR100 = trunc(r, 3)
	}
	// DIVIDE DT-YYYY BY 400 GIVING WS-Q REMAINDER WS-R400
	if 400 != 0 {
		q := CurRec.DtYyyy / 400
		r := CurRec.DtYyyy % 400
		WsQ = trunc(q, 4)
		WsR400 = trunc(r, 3)
	}
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch CurRec.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = trunc(29, 2)
		} else {
			WsMaxDay = trunc(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = trunc(30, 2)
	default:
		WsMaxDay = trunc(31, 2)
	}
}

func main() {
	MainPara()
}
